CAT = "cacesConduite"; SEG = "CON"
# Exploitation : freinage, règles de circulation et de conduite à l'intérieur et à l'extérieur
# des bâtiments, pentes, ponts de liaison, signalisation de sécurité.
# Sources : R489 annexe 2 (G) et annexe 3/1 ; INRS ED 766, § 3.3 à 3.7 ; INRS ED 885
# (arrêté du 4 novembre 1993, forme et couleur des panneaux) ; INRS ED 949, § 2.3.
Q = [
("Chargé, vous descendez une pente prononcée. Comment roulez-vous ?",
 "En marche arrière, mât en arrière", ["En marche avant, mât à la verticale", "En marche avant, fourche haute", "Au point mort, en roue libre"],
 "INRS ED 766, § 3.5 : la descente en charge se fait en principe en marche arrière, mât incliné en arrière, à très faible vitesse, en freinant très progressivement."),
("Dans quel cas pouvez-vous descendre une pente en marche avant avec une charge ?",
 "Pente faible, mât incliné en arrière", ["Charge de moins de 500 kg", "Sol sec et propre, en plein jour", "Jamais, en aucun cas"],
 "INRS ED 766, § 3.5 : si l'angle de la pente est très inférieur à l'inclinaison arrière maximale du mât, on peut descendre en marche avant, mât complètement incliné en arrière."),
("Vous circulez sur un plan incliné et devez faire demi-tour. Où le faites-vous ?",
 "Sur le plat, hors de la pente", ["Dans la pente, à vide", "Dans la pente, en marche arrière", "Dans la pente, fourche haute"],
 "INRS ED 766, § 3.5 : on ne fait pas demi-tour sur un plan incliné : le chariot se trouve en travers de la pente et risque de se renverser."),
("Quelle distance minimale garder entre deux chariots qui roulent dans le même sens ?",
 "Trois longueurs", ["Une longueur", "Deux mètres", "Cinq longueurs"],
 "INRS ED 766, § 3.5 : on maintient une distance suffisante, trois longueurs au minimum, entre deux chariots circulant dans le même sens."),
("À quelle distance au moins d'un rail de voie ferrée arrêtez-vous votre chariot ?",
 "Plus de 1 m", ["Plus de 30 cm", "Plus de 5 m", "Plus de 10 cm"],
 "INRS ED 766, § 3.5 : on arrête le chariot à plus d'un mètre du rail d'une voie ferrée."),
("La charge vous cache la vue vers l'avant. Que faites-vous ?",
 "Je roule en marche arrière", ["Je lève la charge pour voir", "Je roule penché sur le côté", "Je klaxonne et j'avance"],
 "INRS ED 766, § 3.5 : si la visibilité vers l'avant est insuffisante, on circule en marche arrière ou on se fait guider par une personne au sol, sur une courte distance."),
("Rouler en marche arrière à cause d'une charge encombrante doit rester :",
 "Exceptionnel", ["La règle sur tous les trajets", "Réservé aux allées larges", "Réservé aux chariots électriques"],
 "INRS ED 766, § 3.5 : cette manœuvre doit rester exceptionnelle et sur de courtes distances ; sinon, on choisit un chariot mieux adapté ou on réduit la hauteur de la charge."),
("Vous arrivez devant une porte battante va-et-vient. Que faites-vous en premier ?",
 "Je marque un temps d'arrêt", ["Je pousse avec la charge", "J'accélère pour passer", "Je la bloque avec la fourche"],
 "INRS ED 766, § 3.3 : on marque un temps d'arrêt, on actionne l'avertisseur, on regarde si le passage est libre, puis on pousse lentement les battants."),
("Avant de vous engager sur un pont de liaison vers un camion, que vérifiez-vous ?",
 "Sa charge maximale admise", ["Sa date de mise en place", "La couleur de son marquage", "La marque du camion"],
 "INRS ED 766, § 3.3 : on vérifie que le pont est prévu pour le poids total du chariot en charge, que le camion ne peut pas bouger et que le pont est bien en place et amarré."),
("Où est indiquée la charge maximale d'utilisation d'un pont de liaison ?",
 "Sur le pont lui-même", ["Sur la plaque du chariot", "Sur le bon de livraison", "Sur le plan du quai"],
 "INRS ED 766, § 3.3 : la charge maximale d'utilisation doit figurer de façon lisible et indélébile sur le pont lui-même."),
("Vous approchez d'un croisement où des piétons passent. Que faites-vous ?",
 "Je ralentis et j'avertis", ["Je garde ma vitesse", "J'allume les feux de route", "Je lève la fourche"],
 "INRS ED 766, § 3.3 : on ralentit et on avertit aux points dangereux et à l'approche des piétons."),
("Pendant la conduite, où regardez-vous en priorité ?",
 "Dans le sens de la marche", ["Sur la charge en hauteur", "Sur le tableau de bord", "Vers le rayonnage voisin"],
 "INRS ED 766, § 3.3 : on regarde dans le sens de la marche pour conserver une bonne visibilité du parcours, tout en surveillant la charge dans les virages."),
("Quels sont les deux paramètres principaux qui allongent la distance de freinage d'un chariot ?",
 "Vitesse et état du sol", ["Couleur et âge", "Hauteur du mât et dosseret", "Klaxon et éclairage"],
 "R489, annexe 2 (G) : le cariste évalue la distance de freinage selon la vitesse du chariot et la nature du sol ; la charge transportée l'allonge aussi."),
("Si vous doublez la vitesse d'un chariot, sa distance de freinage est à peu près :",
 "Multipliée par 4", ["Multipliée par 2", "Inchangée", "Divisée par 2"],
 "Notion de physique (R489, annexe 2, D et G) : l'énergie à dissiper croît comme le carré de la vitesse, donc à freinage égal deux fois plus vite donne environ quatre fois plus de distance."),
("Comment freinez-vous en conduite normale ?",
 "Progressivement", ["Brutalement pour s'arrêter net", "Seulement avec le frein de parc", "En inversant la marche"],
 "INRS ED 766, § 3.5 : on freine progressivement et sans brutalité ; un freinage brusque déstabilise la charge et le chariot."),
("Dans l'entreprise, quelles règles de circulation suit le cariste ?",
 "Celles de l'entreprise", ["Seulement le Code de la route", "Aucune règle précise", "Celles du fabricant"],
 "INRS ED 766, § 3.3 : on observe les signaux et règles de circulation en vigueur dans l'entreprise ; sur une voie ouverte à la circulation publique, le Code de la route s'ajoute."),
("Le chariot emprunte une voie ouverte à la circulation publique. Que respectez-vous en plus des règles de l'entreprise ?",
 "Le Code de la route", ["Le règlement intérieur seul", "La notice du chariot seule", "Rien de plus"],
 "INRS ED 766, § 3.5 : en cas de circulation sur une voie ouverte à la circulation publique, on observe en plus les prescriptions du Code de la route."),
("Quels itinéraires un cariste emprunte-t-il dans l'entreprise ?",
 "Ceux du plan de circulation", ["Le chemin le plus court", "Toute allée assez large", "Les allées des piétons"],
 "INRS ED 766, § 3.9 : il est interdit d'emprunter des circuits de circulation autres que ceux établis par le plan de circulation."),
("Quelle forme et quelle couleur a un panneau d'interdiction sur un lieu de travail ?",
 "Rond, barré de rouge", ["Triangle à fond jaune", "Rond à fond bleu", "Carré à fond vert"],
 "INRS ED 885 (arrêté du 4 novembre 1993) : les panneaux d'interdiction sont ronds, cerclés et barrés de rouge."),
("Un panneau triangulaire à fond jaune montre un chariot élévateur noir. Que signifie-t-il ?",
 "Chariots en circulation", ["Accès interdit aux chariots", "Parking des chariots", "Chariots obligatoires"],
 "INRS ED 885 : les panneaux triangulaires à fond jaune sont des avertissements ; celui-ci avertit de la présence de chariots élévateurs."),
("Un panneau rond à fond bleu montre un casque blanc. Que signifie-t-il ?",
 "Casque obligatoire", ["Casque interdit", "Casque conseillé", "Vestiaire des casques"],
 "INRS ED 885 : les panneaux d'obligation sont ronds, à fond bleu avec un pictogramme blanc ; ici, le port du casque de protection est obligatoire."),
("Un panneau rond cerclé et barré de rouge montre un chariot élévateur. Que signifie-t-il ?",
 "Interdit aux chariots", ["Attention aux chariots", "Réservé aux chariots", "Aire de charge"],
 "INRS ED 885 : ce panneau d'interdiction signifie que l'accès est interdit aux chariots ; un triangle jaune avec un chariot signalerait seulement leur présence."),
("Que signale un panneau carré à fond vert avec un pictogramme blanc ?",
 "Sauvetage ou secours", ["Matériel d'incendie", "Danger électrique", "Zone interdite aux piétons"],
 "INRS ED 885 : les panneaux de sauvetage et de secours sont carrés ou rectangulaires, pictogramme blanc sur fond vert ; ceux du matériel d'incendie sont blancs sur fond rouge."),
("Que signalent des bandes alternées jaunes et noires sur un poteau ou un quai ?",
 "Un risque de heurt", ["Une zone de parking", "Une sortie de secours", "Une prise électrique"],
 "INRS ED 885 : la signalisation de risque ou de danger se fait par bandes jaunes et noires ou rouges et blanches, pour les obstacles et les risques de chute."),
("Un panneau carré à fond rouge avec un pictogramme blanc indique :",
 "Un matériel d'incendie", ["Une interdiction", "Une issue de secours", "Un poste de premiers soins"],
 "INRS ED 885 : le matériel ou l'équipement de lutte contre l'incendie est signalé par des panneaux carrés ou rectangulaires, pictogramme blanc sur fond rouge."),
("Le chariot circule de nuit dans une cour mal éclairée. De quoi doit-il être équipé ?",
 "De feux avant et arrière", ["D'un second contrepoids", "D'un dosseret plus haut", "D'une rallonge de fourche"],
 "INRS ED 766, § 2.2.2 : le chariot qui circule la nuit ou dans des zones insuffisamment éclairées doit être équipé de feux avant et arrière."),
("Avant d'entrer dans une allée avec un chariot à poste élevable, que vérifiez-vous ?",
 "Que personne n'y circule", ["Que la batterie est pleine", "Que l'allée est éclairée en bleu", "Que la fourche est en haut"],
 "INRS ED 766, § 3.7 : avant d'engager un chariot à poste de conduite élevable dans une allée, on s'assure que personne ne circule dans celle-ci."),
("Depuis le poste élevable d'un préparateur de commandes, un colis est hors d'atteinte. Que faites-vous ?",
 "Je déplace le chariot", ["Je sors du poste pour le prendre", "Je grimpe au rayonnage", "Je me penche par-dessus le garde-corps"],
 "INRS ED 766, § 3.7 : il ne faut pas s'extraire du poste de conduite d'un préparateur de commandes pour saisir un colis dans un rayonnage ; on repositionne le chariot."),
]
